{
  "decision-indivisible-racks-on-a-lift-truck": "WITH loads(first_rack, second_rack, used_slots, saved_trips) AS (SELECT rack_id, NULL, slot_use, saved_trips FROM rack_offer UNION ALL SELECT a.rack_id, b.rack_id, a.slot_use + b.slot_use, a.saved_trips + b.saved_trips FROM rack_offer AS a JOIN rack_offer AS b ON a.rack_id COLLATE BINARY < b.rack_id) SELECT l.first_rack, l.second_rack, l.used_slots, l.saved_trips, t.source_id FROM loads AS l CROSS JOIN truck_card AS t WHERE l.used_slots <= t.slot_limit ORDER BY l.saved_trips DESC, l.used_slots ASC, l.first_rack COLLATE BINARY ASC, l.second_rack COLLATE BINARY ASC LIMIT 1",
  "decision-inspection-possession-displacement": "SELECT p.permit_id, COUNT(b.booking_id) AS canceled_qty, COALESCE(SUM(b.cancel_cents), 0) AS compensation_cents FROM possession_permit AS p LEFT JOIN service_booking AS b ON EXISTS (SELECT 1 FROM throat_move AS m WHERE m.booking_id = b.booking_id AND m.enter_min < p.end_min AND p.start_min < m.leave_min) GROUP BY p.permit_id, p.start_min HAVING COUNT(b.booking_id) = COUNT(b.cancel_cents) ORDER BY compensation_cents ASC, canceled_qty ASC, p.start_min ASC, p.permit_id COLLATE BINARY ASC LIMIT 1",
  "decision-instant-runoff-design-ballot": "WITH designs(code) AS (VALUES ('A'), ('B'), ('C')), total(n) AS (SELECT COALESCE(SUM(ballot_count), 0) FROM ballots), r1 AS (SELECT d.code, COALESCE(SUM(b.ballot_count), 0) AS votes FROM designs AS d LEFT JOIN ballots AS b ON b.first_choice = d.code GROUP BY d.code), eliminated AS (SELECT code FROM r1 ORDER BY votes ASC, code COLLATE BINARY DESC LIMIT 1), r2 AS (SELECT d.code, COALESCE(SUM(b.ballot_count), 0) AS votes FROM designs AS d CROSS JOIN eliminated AS e LEFT JOIN ballots AS b ON d.code = CASE WHEN b.first_choice = e.code THEN b.second_choice ELSE b.first_choice END WHERE d.code <> e.code GROUP BY d.code), finalist AS (SELECT code FROM r2 ORDER BY votes DESC, code COLLATE BINARY ASC LIMIT 1), winners(winner, winning_round, winning_votes) AS (SELECT code, 1, votes FROM r1, total WHERE votes > n / 2 UNION ALL SELECT code, 2, votes FROM r2, total WHERE votes > n / 2 UNION ALL SELECT code, 3, n FROM finalist, total) SELECT winner, winning_round, winning_votes FROM winners ORDER BY winning_round ASC LIMIT 1",
  "decision-integrate-drying-sheet-area": "WITH segments AS (SELECT LEAD(elapsed_s) OVER seq - elapsed_s AS dt, width_cm AS w0, length_cm AS l0, LEAD(width_cm) OVER seq AS w1, LEAD(length_cm) OVER seq AS l1 FROM sheet_samples WINDOW seq AS (ORDER BY elapsed_s)) SELECT SUM(dt * (2 * w0 * l0 + w0 * l1 + w1 * l0 + 2 * w1 * l1)) / 6 AS area_cm2_s FROM segments WHERE dt IS NOT NULL"
}
